# Generated by tools/sr_mod_sdk_export.py; edit shared sources.
"""Closed public hook contracts and generated public-only ABI adapters.

Addresses, names and prototypes come from the requesting compiler graph.
Construction is not loader admission, game-layout proof or game parity.
"""
from pathlib import Path
import re

from .sr_mod_object import (GUEST_WIDTH_INTEGERS, NATIVE_WIDTH_INTEGERS, ModObjectError, canonical_type,
                            constant_integer, integer_pointer_operand, nodes, span, strip_casts,
                            supported_type)
from .sr_mod_patch_declarations import closed_compiler_bindings
from .sr_mod_sdk_requests import PublicRequests, unwrap

FIELDS = ['struct_size', 'behavior', 'hook_id', 'target_library', 'symbol',
          'offset', 'replacement', 'original']


def qualified_name(node, parents):
    names = [node['name']]
    while id(node) in parents:
        node = parents[id(node)]
        if node.get('kind') == 'NamespaceDecl' and node.get('name'):
            names.append(node['name'])
    return '::'.join(reversed(names))


def extract_public_hooks(root):
    bindings = closed_compiler_bindings(root, capture_slots=True)
    rows, declarations, parents = (bindings[name] for name in ('rows', 'declarations', 'parents'))
    evaluate, contexts = (bindings[name] for name in ('evaluate', 'contexts'))
    public = PublicRequests(rows, declarations, parents, service='hook_function',
                            record='mf_function_hook_v1', fields=FIELDS, label='HOOK')
    public.validate_services()
    functions = {}
    for node in rows:
        if node.get('kind') == 'FunctionDecl' and node.get('mangledName') and any(
                child.get('kind') == 'CompoundStmt' for child in node.get('inner', ())):
            functions[node['mangledName']] = node
    hooks, sites = [], []
    for row in rows:
        if not public.service_call(row):
            continue
        request = public.request(row)
        target = unwrap(row['inner'][0])
        sites.append(dict(call=row, receiver=target['inner'][0]))
        for environment in contexts(row):
            replacement = evaluate(request['replacement'], environment).value
            original = evaluate(request['original'], environment).value
            if not isinstance(replacement, dict) or 'callback' not in replacement or \
                    replacement['callback'] not in functions:
                raise ModObjectError('PUBLIC_HOOK_TYPED_CALLBACK_REQUIRED')
            if original != 0 and (not isinstance(original, dict) or not original.get('original')):
                raise ModObjectError('PUBLIC_HOOK_TYPED_ORIGINAL_SLOT_REQUIRED')
            callback = functions[replacement['callback']]
            library = evaluate(request['target_library'], environment).value
            offset = evaluate(request['offset'], environment).value
            symbol = unwrap(request['symbol'])
            if not isinstance(library, str) or not library.startswith('"') or not library.endswith('"') or \
                    not library[1:-1] or chr(92) in library or type(offset) is not int or not 0 < offset < 2**32:
                raise ModObjectError('PUBLIC_HOOK_STATIC_TARGET_REQUIRED')
            if symbol.get('kind') not in ('ImplicitValueInitExpr', 'CXXNullPtrLiteralExpr', 'GNUNullExpr') and \
                    not (symbol.get('kind') == 'IntegerLiteral' and int(symbol.get('value', '-1')) == 0):
                raise ModObjectError('PUBLIC_HOOK_EXACT_OFFSET_TARGET_REQUIRED')
            if original != 0 and canonical_type(callback).replace(' ', '') != original['prototype'].replace(' ', '').replace('(*)', ''):
                raise ModObjectError('PUBLIC_HOOK_ORIGINAL_PROTOTYPE_MISMATCH')
            candidate = dict(callback=callback['mangledName'], name=qualified_name(callback, parents),
                original=original['original'] if original != 0 else None, prototype=canonical_type(callback),
                target_library=library[1:-1], offset=offset, identifier=callback['id'])
            previous = next((hook for hook in hooks if hook['callback'] == candidate['callback']), None)
            if previous and previous != candidate:
                raise ModObjectError('PUBLIC_HOOK_DISTINCT_CALLBACK_CONTRACT_REQUIRED')
            if previous is None:
                hooks.append(candidate)
    return hooks, sites


def public_adapter_view(source_bytes, root, source, abi_types, edits=None):
    hooks, sites = extract_public_hooks(root)
    edits = dict(edits or {})
    if not hooks:
        return apply_edits(source_bytes, edits), []
    lines = ['#include <mod_compat.hpp>',
        'static mf_result_v1 __armport_public_hook(const mf_api_v1*, const mf_mod_context_v1*, const mf_function_hook_v1*);']
    suffix = ['static mf_result_v1 __armport_public_hook(const mf_api_v1* api,',
        'const mf_mod_context_v1* context, const mf_function_hook_v1* request) {',
        'if (!request) return MF_ERROR_INVALID_ARGUMENT;']
    contracts = []
    for index, hook in enumerate(hooks):
        abi = abi_types.get(hook['identifier'])
        if not abi or abi.get('result_handle') or any(abi.get('argument_handles', ())):
            raise ModObjectError('PUBLIC_HOOK_COMPILER_SCALAR_OR_MEMORY_ABI_REQUIRED')
        if not supported_type(abi['result'], result=True) or any(
                not supported_type(value) for value in abi['arguments']):
            raise ModObjectError('PUBLIC_HOOK_GAME_LAYOUT_OR_RESOURCE_ADAPTER_REQUIRED')
        signature = abi['result']+' (*)('+', '.join(abi['arguments'])+')'
        suffix += ['if (request->replacement == reinterpret_cast<void*>(&'+hook['name']+')) {',
            'struct Tag'+str(index)+' {};',
            'using Adapter = mf::compat::GameHook<'+signature+', &'+hook['name']+', Tag'+str(index)+'>;',
            'return Adapter::install(api, context, request); }']
        contracts.append({key: value for key, value in hook.items() if key != 'identifier'})
        contracts[-1]['source_abi'] = abi
    suffix += ['return MF_ERROR_DENIED;', '}']
    for site in sites:
        begin, end = span(site['call'], source)
        receiver_begin, receiver_end = span(site['receiver'], source)
        arguments = [source_bytes[slice(*span(argument, source))] for argument in site['call']['inner'][1:]]
        replacement = b'__armport_public_hook('+source_bytes[receiver_begin:receiver_end]+b', '+b', '.join(arguments)+b')'
        if (begin, end) in edits and edits[begin, end] != replacement:
            raise ModObjectError('PUBLIC_HOOK_CONFLICTING_TEMPLATE_VIEW')
        edits[begin, end] = replacement
    source_bytes = apply_edits(source_bytes, edits)
    return ('\n'.join(lines)+'\n').encode()+source_bytes+('\n'+'\n'.join(suffix)+'\n').encode(), contracts


def apply_edits(source_bytes, edits):
    """Replacements by (begin, end) byte range; begin == end inserts."""
    previous = len(source_bytes)
    for (begin, end), replacement in sorted(edits.items(), reverse=True):
        if end > previous:
            raise ModObjectError('PUBLIC_HOOK_OVERLAPPING_VIEW')
        source_bytes = source_bytes[:begin]+replacement+source_bytes[end:]
        previous = begin
    return source_bytes


# Game functions called through a resolved address: the compiler graph supplies
# each ARMv7 prototype; the framework adapts the call (mf_game_function_v1).
CALL_SERVICES = {'resolve_game_symbol': 3, 'resolve_game_address': 5}
CALL_LETTERS = {'void': 'v', 'bool': 'b', '_Bool': 'b', 'char': 'C', 'signed char': 'c',
                'unsigned char': 'C', 'short': 's', 'unsigned short': 'S', 'int': 'i',
                'unsigned int': 'I', 'long': 'i', 'unsigned long': 'I', 'long long': 'l',
                'unsigned long long': 'L', 'float': 'f', 'double': 'd'}


# What to declare instead, by reason code.
CALL_ADVICE = {
    'VARIADIC': 'declare only the fixed arguments you pass; format text in the mod and pass "%s" with it',
    'CALLBACK': 'game code cannot call native mod functions; hook the game function that calls it instead',
    'REFERENCE': 'declare it as a pointer (const T* for const T&) to game-visible memory',
    'RECORD': 'pass a struct as a pointer, or, if every field is 4 bytes (e.g. float x, y), as its fields '
              'in order; an enum as int',
    'RECORD_RESULT': 'declare a pointer to a static or heap result buffer as the first argument and return void, '
                     'or return an int if the result is 4 bytes or less',
    'LONG_DOUBLE': 'declare it as double (the game\'s long double is a double)',
    'TYPE': 'use a fixed-width integer, float, double or pointer type',
}


def call_failure(reason, prototype):
    return ModObjectError('PUBLIC_GAME_CALL_%s %s: %s' % (reason, prototype, CALL_ADVICE[reason]))


def call_signature(prototype):
    """An ARMv7 function pointer type as mf_game_function_v1 signature letters."""
    match = re.fullmatch(r'(.+?)\s*\(\*\)\((.*)\)', ' '.join(prototype.split()))
    if not match:
        raise call_failure('TYPE', prototype)
    if '...' in match[2]:
        raise call_failure('VARIADIC', prototype)
    if '(' in match[2]:
        raise call_failure('CALLBACK', prototype)
    arguments = [part for part in match[2].split(',')] if match[2].strip() not in ('', 'void') else []
    letters = ''
    for value in [match[1], *arguments]:
        plain = ' '.join(re.sub(r'\b(const|volatile)\b', ' ', value).split())
        if '&' in plain:
            raise call_failure('REFERENCE', prototype)
        letter = 'p' if plain.endswith('*') else CALL_LETTERS.get(plain)
        if letter is None:
            builtin = plain == 'long double' or plain in ('wchar_t', 'char16_t', 'char32_t', '__int128',
                                                         'unsigned __int128', '__fp16', '_Float16')
            reason = 'LONG_DOUBLE' if plain == 'long double' else 'TYPE' if builtin else \
                'RECORD' if letters else 'RECORD_RESULT'
            raise call_failure(reason, prototype)
        if letters and letter == 'v':
            raise call_failure('TYPE', prototype)
        letters += letter
    return letters


def extract_public_calls(root):
    """Results of resolve_game_symbol/resolve_game_address converted straight to a function
    pointer, with static targets. Any source file; other uses are data and stay untouched."""
    rows = list(nodes(root))
    parents = {id(child): row for row in rows for child in row.get('inner', ())}
    declarations = {row['id']: row for row in rows if row.get('kind') == 'VarDecl' and row.get('id')}

    def literal(node):
        node = unwrap(node)
        if node.get('kind') == 'DeclRefExpr':
            declaration = declarations.get(node.get('referencedDecl', {}).get('id'), {})
            node = unwrap(declaration['inner'][-1]) if declaration.get('inner') else {}
        if node.get('kind') != 'StringLiteral':
            raise ModObjectError('PUBLIC_GAME_CALL_STATIC_TARGET_REQUIRED')
        return node['value']

    calls = {}
    for row in rows:
        callee = unwrap(row['inner'][0]) if row.get('kind') == 'CallExpr' and row.get('inner') else {}
        count = CALL_SERVICES.get(callee.get('name')) if callee.get('kind') == 'MemberExpr' else None
        if count is None or len(row['inner']) != count+1:
            continue
        use = parents.get(id(row))
        while use and use.get('kind') in ('ImplicitCastExpr', 'ParenExpr') and '(*)' not in canonical_type(use):
            use = parents.get(id(use))
        if not use or '(*)' not in canonical_type(use):
            continue
        arguments = row['inner'][2:]
        symbol = literal(arguments[1]) if callee['name'] == 'resolve_game_symbol' else None
        call = dict(library=literal(arguments[0]), symbol=symbol,
                    offset=0 if symbol else constant_integer(unwrap(arguments[1]), declarations),
                    signature=call_signature(canonical_type(use)))
        if calls.setdefault((call['library'], symbol, call['offset']), call)['signature'] != call['signature']:
            raise ModObjectError('PUBLIC_GAME_CALL_CONFLICTING_PROTOTYPES')
    return list(calls.values())


def public_call_table(calls, cpp):
    """The exported table the framework reads when it loads the package."""
    rows = ''.join('    {%s, %s, 0x%x, "%s"},\n' % (call['library'], call['symbol'] or '0', call['offset'],
                   call['signature']) for call in calls)
    return ('\n'+('extern "C" ' if cpp else '')+'__attribute__((visibility("default"), used))\n'
            'const mf_game_function_v1 mf_game_functions_v1[] = {\n'+rows+'    {0, 0, 0, 0}\n};\n').encode()


# A 32-bit integer converted to a pointer is a game address (the rule built-ins
# follow too: uintptr_t for native addresses, uint32_t for game ones). Game
# memory is not at its game address on ARM64, so the build maps each such
# conversion through the framework's import (MF_GAME_POINTER_SYMBOL).
GAME_POINTER = 'mf_game_pointer_v1'
POINTER_ADVICE = {
    'CODE': 'a game function address cannot be called natively; call game functions through '
            'resolve_game_symbol or resolve_game_address, or hook them',
    'MACRO': 'convert game addresses in a function, not in a macro',
    'HEADER': 'keep files that convert game addresses in the folder of the mod source or below it',
}


def location_files(root):
    """The file of each source location; the compiler dump names it only where it changes."""
    files, current, pending = {}, None, [root]
    while pending:
        value = pending.pop()
        if isinstance(value, dict):
            if 'offset' in value:
                current = value.get('file', current)
                files[id(value)] = current
            pending.extend(reversed(list(value.values())))
        elif isinstance(value, list):
            pending.extend(reversed(value))
    return files


def native_operand(node):
    """A pointer-width value or converted pointer anywhere in the integer expression:
    native address arithmetic (uintptr_t base + offset) stays native."""
    node = integer_pointer_operand(node)
    spelled = node.get('type', {}).get('qualType', '').removeprefix('const ')
    if spelled in NATIVE_WIDTH_INTEGERS or canonical_type(node).removeprefix('const ') in NATIVE_WIDTH_INTEGERS or \
            node.get('castKind') == 'PointerToIntegral':
        return True
    children = node.get('inner', ())
    if node.get('kind') == 'ConditionalOperator':
        children = children[1:]
    elif node.get('kind') not in ('BinaryOperator', 'UnaryOperator'):
        return False
    return any(native_operand(child) for child in children)


def public_game_pointers(root, source, cpp):
    """Edits for every package file of the compile (the source folder and below), and the
    converted (file, offset) operands: each 32-bit game address converted to a pointer goes
    through GAME_POINTER. Native-width values and literals (sentinels) stay as written."""
    files, folder = location_files(root), Path(source).resolve().parent
    package = {}
    for name in set(files.values()):
        path = Path(name).resolve() if name and not name.startswith('<') else None
        if path and path.is_file() and path.is_relative_to(folder):
            package[path] = {}
    seen = set()
    for row in nodes(root):
        if row.get('kind') not in ('CStyleCastExpr', 'CXXReinterpretCastExpr', 'CXXFunctionalCastExpr') or \
                row.get('castKind') != 'IntegralToPointer' or len(row.get('inner', ())) != 1:
            continue
        operand = integer_pointer_operand(row['inner'][0])
        value = strip_casts(operand['inner'][0]) if operand.get('kind') == 'UnaryOperator' else operand
        if value.get('kind') in ('IntegerLiteral', 'ConstantExpr') or native_operand(operand) or \
                canonical_type(operand).removeprefix('const ') not in GUEST_WIDTH_INTEGERS:
            continue
        reason = 'CODE' if '(*)' in canonical_type(row) else None
        cast_begin = row.get('range', {}).get('begin', {})
        location = row['inner'][0].get('range', {})
        begin, end = location.get('begin', {}), location.get('end', {})
        if not reason and any('offset' not in item for item in (cast_begin, begin, end)):
            reason = 'MACRO'
        path = Path(files[id(begin)]).resolve() if not reason else None
        if not reason and (path not in package or files[id(end)] != files[id(begin)]):
            reason = 'HEADER'
        if reason:
            raise ModObjectError('PUBLIC_GAME_POINTER_%s %s: %s' % (
                reason, canonical_type(row), POINTER_ADVICE[reason]))
        first, last = begin['offset'], end['offset']+end['tokLen']
        if (path, first, last) in seen:
            continue  # template instantiations share their pattern's text
        seen.add((path, first, last))
        edits = package[path]
        edits[first, first] = (GAME_POINTER+'(').encode()+edits.get((first, first), b'')
        edits[last, last] = edits.get((last, last), b'')+b')'
    declaration = (('extern "C" ' if cpp else '')+'void* '+GAME_POINTER+'(unsigned long long);\n').encode()
    for edits in package.values():
        if edits:
            edits[0, 0] = declaration+edits.get((0, 0), b'')
    return package, sorted((path, first) for path, first, _ in seen)
